const BARE = {
  "@figentra-oss/flow/guard": "src/guard/index.mjs",
  "@figentra-oss/flow/guard/neutral": "src/guard/neutral.mjs",
};

const GUARD = {
  "bash-rules.mjs": "preset/guard/bash-rules.mjs",
  "path-rules.mjs": "preset/guard/path-rules.mjs",
  "hints.mjs": "preset/guard/hints.mjs",
};

const BASE = new URL("./fflow-guard/", import.meta.url).href;

process.exit(await boot(FILES, BARE, GUARD, process.argv[2] ?? "", registerHooks, BASE));

async function boot(files, bare, guard, event, register, base) {
  const url = (/** @type {string} */ path) => new URL(path, base).href;
  const sources = new Map(Object.entries(files).map(([path, text]) => [url(path), text]));
  register({
    resolve(specifier, context, next) {
      const to = bare[specifier]
        ? url(bare[specifier])
        : /^(\.\.?\/|file:)/.test(specifier)
          ? new URL(specifier, context.parentURL).href
          : "";
      return sources.has(to) ? { url: to, shortCircuit: true } : next(specifier, context);
    },
    load(href, context, next) {
      const source = sources.get(href);
      return source === undefined
        ? next(href, context)
        : { format: "module", source, shortCircuit: true };
    },
  });
  const { main } = await import(url("src/guard/engine.mjs"));
  return main(event, async (/** @type {string} */ file) =>
    guard[file] ? import(url(guard[file])) : undefined,
  );
}
